namespace sv_5c2e280008fc40f1bde31e119b5fd1a8.Client.Services;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

namespace sv_5c2e280008fc40f1bde31e119b5fd1a8.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_5c2e280008fc40f1bde31e119b5fd1a8.Client.Services;

/// <summary>
/// Client-side implementation that calls the server API over HTTP.
/// Used when the component runs on WebAssembly.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_5c2e280008fc40f1bde31e119b5fd1a8.Client.Services;

namespace sv_5c2e280008fc40f1bde31e119b5fd1a8.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with fake data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 7, 17, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate("Package picked up", "New York, NY", new DateTimeOffset(2026, 6, 1, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Departed facility", "New York, NY", new DateTimeOffset(2026, 6, 1, 14, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Arrived at sorting center", "Chicago, IL", new DateTimeOffset(2026, 6, 2, 6, 15, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit to destination", "Chicago, IL", new DateTimeOffset(2026, 6, 3, 8, 0, 0, TimeSpan.Zero)),
            ]),

        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 2, 12, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 5, 29, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit", "Portland, OR", new DateTimeOffset(2026, 5, 30, 15, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 2, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 2, 11, 45, 0, TimeSpan.Zero)),
            ]),

        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 10, 18, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate("Label created", "Dallas, TX", new DateTimeOffset(2026, 6, 3, 7, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Awaiting pickup", "Dallas, TX", new DateTimeOffset(2026, 6, 3, 7, 5, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

